package service

import (
	"fmt"
	"sync"
	"github.com/google/uuid" // Will be used later for ID generation
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService defines the interface for user-related business logic
type UserService interface {
	GetAllUsers() []User
	GetUserByID(id string) (User, bool)
	CreateUser(user User) (User, error)
}

// userService implements UserService
type userService struct {
	users  map[string]User
	mutex  sync.RWMutex
	nextID int // This will be replaced by uuid in a later step
}

// NewUserService creates and returns a new UserService
func NewUserService() UserService {
	return &userService{
		users:  make(map[string]User),
		mutex:  sync.RWMutex{},
		nextID: 1,
	}
}

func (s *userService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

func (s *userService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	u, ok := s.users[id]
	return u, ok
}

func (s *userService) CreateUser(user User) (User, error) {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	// For now, using simple integer ID. Will upgrade to uuid later.
	user.ID = fmt.Sprintf("%d", s.nextID)
	s.nextID++
	s.users[user.ID] = user
	return user, nil
}

package api

import (
	"encoding/json"
	"net/http"

	"legacy_refactor/rep-10/internal/service"
)

// UserHandlers holds the dependencies for user HTTP handlers
type UserHandlers struct {
	UserService service.UserService
}

// NewUserHandlers creates and returns new UserHandlers
func NewUserHandlers(userService service.UserService) *UserHandlers {
	return &UserHandlers{
		UserService: userService,
	}
}

// HandleUsers manages requests to /users
func (h *UserHandlers) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		h.GetUsers(w, r)
	case http.MethodPost:
		h.CreateUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetUsers handles GET requests for /users
func (h *UserHandlers) GetUsers(w http.ResponseWriter, r *http.Request) {
	users := h.UserService.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUser handles POST requests for /users
func (h *UserHandlers) CreateUser(w http.ResponseWriter, r *http.Request) {
	var user service.User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser, err := h.UserService.CreateUser(user)
	if err != nil {
		http.Error(w, err.Error(), http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// HandleUserByID manages requests to /users/{id}
func (h *UserHandlers) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	switch r.Method {
	case http.MethodGet:
		h.GetUserByID(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetUserByID handles GET requests for /users/{id}
func (h *UserHandlers) GetUserByID(w http.ResponseWriter, r *http.Request, id string) {
	user, ok := h.UserService.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(user)
}

package main

import (
	"log"
	"net/http"

	"legacy_refactor/rep-10/internal/api"
	"legacy_refactor/rep-10/internal/service"
)

func main() {
	// Initialize service layer
	userService := service.NewUserService()

	// Initialize API handlers
	userHandlers := api.NewUserHandlers(userService)

	// Register HTTP routes
	http.HandleFunc("/users", userHandlers.HandleUsers)
	http.HandleFunc("/users/", userHandlers.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"legacy_refactor/rep-10/internal/service"
)

func TestUserAPI(t *testing.T) {
	// Initialize service and handlers for testing
	userService := service.NewUserService()
	userHandlers := api.NewUserHandlers(userService)

	// Register routes only for the test server
	mux := http.NewServeMux()
	mux.HandleFunc("/users", userHandlers.HandleUsers)
	mux.HandleFunc("/users/", userHandlers.HandleUserByID)

	// Test server
	ts := httptest.NewServer(mux)
	defer ts.Close()

	// Test POST /users (Create User)
	user := service.User{Name: "John Doe", Email: "john.doe@example.com"}
	jsonUser, _ := json.Marshal(user)

	res, err := ts.Client().Post(ts.URL+"/users", "application/json", bytes.NewBuffer(jsonUser))
	if err != nil {
		t.Fatalf("Failed to send POST request: %v", err)
	}
	defer res.Body.Close()

	if res.StatusCode != http.StatusCreated {
		t.Errorf("Expected status %d for POST, got %d", http.StatusCreated, res.StatusCode)
	}

	var createdUser service.User
	json.NewDecoder(res.Body).Decode(&createdUser)
	if createdUser.Name != user.Name || createdUser.Email != user.Email || createdUser.ID == "" {
		t.Errorf("Unexpected created user: %+v", createdUser)
	}

	// Test GET /users (Get All Users)
	res, err = ts.Client().Get(ts.URL + "/users")
	if err != nil {
		t.Fatalf("Failed to send GET request: %v", err)
	}
	defer res.Body.Close()

	if res.StatusCode != http.StatusOK {
		t.Errorf("Expected status %d for GET, got %d", http.StatusOK, res.StatusCode)
	}

	var users []service.User
	json.NewDecoder(res.Body).Decode(&users)
	if len(users) != 1 || users[0].ID != createdUser.ID {
		t.Errorf("Unexpected users list: %+v", users)
	}

	// Test GET /users/{id} (Get User By ID)
	res, err = ts.Client().Get(ts.URL + "/users/" + createdUser.ID)
	if err != nil {
		t.Fatalf("Failed to send GET request: %v", err)
	}
	defer res.Body.Close()

	if res.StatusCode != http.StatusOK {
		t.Errorf("Expected status %d for GET by ID, got %d", http.StatusOK, res.StatusCode)
	}

	var fetchedUser service.User
	json.NewDecoder(res.Body).Decode(&fetchedUser)
	if fetchedUser.ID != createdUser.ID || fetchedUser.Name != createdUser.Name {
		t.Errorf("Unexpected fetched user: %+v", fetchedUser)
	}

	// Test GET /users/{non-existent-id} (Get Non-Existent User)
	res, err = ts.Client().Get(ts.URL + "/users/non-existent-id")
	if err != nil {
		t.Fatalf("Failed to send GET request: %v", err)
	}
	defer res.Body.Close()

	if res.StatusCode != http.StatusNotFound {
		t.Errorf("Expected status %d for non-existent user, got %d", http.StatusNotFound, res.StatusCode)
	}
}
